(function(){
'use strict';
const L=window.LESSON,C=window.LearningCore,E=C.escape;
const STORE='storysprout:'+L.id;
let persistence=true;
let p;try{p=C.clean(JSON.parse(localStorage.getItem(STORE)||'null'),L);}catch{p=C.initial();persistence=false;}
let view='read',translation=false,phrases=false,checkpoint=false,chapterFeedback=null,wordFilter='all',search='',wordMode='cards';
let challenge='quiz',qIndex=0,qFeedback=null,qHint=false,quizDone=false,quizSession=0;
let orderPool=C.shuffle(L.order.map((_,i)=>i)),orderAnswer=[],orderFeedback='';
let builder=0,builderPool=C.shuffle(L.builders[0].parts.map((_,i)=>i)),builderAnswer=[],builderFeedback='';
let matchWords=[],matchRight=[],matchDone=[],matchLeft=null,matchSelection=null;
let retellHints=true,extension='museums',role='friend',roleIndex=0,museumMatches={};
let speakToken=0,speaking=false,currentUtterance=null,activeSpeechButton=null;
let timer=null,toastTimer=null,lastInteraction=Date.now(),lastTick=Date.now();
let recorder=null,recordStream=null,recordChunks=[],recordURL='',recordBlob=null,recordTimeout=null,recordStart=0,recordBusy=false;
let dialogReturnFocus=null;
const questions=[...L.chapters.map((c,i)=>({...c.quiz,chapter:i})),...L.extraQuestions];
const vocabMap=new Map(L.vocabulary.map(w=>[w[0].toLowerCase(),w]));
const aliases={secret:'secrets',window:'windows',switch:'switched',check:'checked',arrive:'arrived',lock:'locked',wait:'waited',enjoy:'enjoyed',show:'showed',spend:'spending'};
const icons={
 book:'<path d="M3 4h6a4 4 0 0 1 3 2 4 4 0 0 1 3-2h6v15h-6a4 4 0 0 0-3 2 4 4 0 0 0-3-2H3z"/><path d="M12 6v15"/>',
 cat:'<path d="M5 13V3l6 5h2l6-5v10a7 7 0 0 1-14 0Z"/><path d="M8 12h1m6 0h1m-5 3 1 1 1-1M3 16l4-1m10 0 4 1"/>',
 compass:'<circle cx="12" cy="12" r="9"/><path d="m16 8-2 6-6 2 2-6z"/>',
 cards:'<rect x="4" y="5" width="13" height="16" rx="2"/><path d="m8 3 11-1 3 16-3 1M8 10h5m-5 4h5"/>',
 star:'<path d="m12 3 2.7 5.5 6.1.9-4.4 4.3 1 6-5.4-2.8L6.6 20l1-6-4.4-4.3 6.1-.9z"/>',
 trophy:'<path d="M7 3h10v5a5 5 0 0 1-10 0zM7 5H3v3a4 4 0 0 0 4 4m10-7h4v3a4 4 0 0 1-4 4M12 13v6m-5 2h10m-8-2h6"/>',
 mic:'<rect x="9" y="2" width="6" height="13" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2m-7 9v3m-4 0h8"/>',
 museum:'<path d="m2 8 10-5 10 5M3 9h18M5 10v8m5-8v8m4-8v8m5-8v8M3 19h18M2 22h20"/>',
 volume:'<path d="M4 9h4l5-4v14l-5-4H4zM16 8a6 6 0 0 1 0 8m3-11a10 10 0 0 1 0 14"/>',
 arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',
 back:'<path d="M20 12H4m6-6-6 6 6 6"/>',
 check:'<path d="m5 12 5 5L20 6"/>',
 close:'<path d="m6 6 12 12M18 6 6 18"/>',
 settings:'<path d="M4 6h16M4 12h16M4 18h16"/><circle cx="9" cy="6" r="2" fill="currentColor"/><circle cx="16" cy="12" r="2" fill="currentColor"/><circle cx="7" cy="18" r="2" fill="currentColor"/>',
 search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>',
 bulb:'<path d="M8 17c0-5-3-4-3-9a7 7 0 0 1 14 0c0 5-3 4-3 9zm1 4h6m-5-4v-6h4v6"/>',
 sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',
 moon:'<path d="M20 14A9 9 0 0 1 10 3a9 9 0 1 0 10 11z"/>',
 torch:'<path d="m7 10 4 4-6 7-3-3zm-1-1 6-6 5 5-5 6zM17 1v3m4 4h-3m3-6-3 3"/>',
 repeat:'<path d="M3 10a9 9 0 0 1 15-6l3 3M21 3v4h-4M21 14A9 9 0 0 1 6 20l-3-3M3 21v-4h4"/>',
 stop:'<rect x="5" y="5" width="14" height="14" rx="2"/>',
 play:'<path d="m7 4 13 8-13 8z"/>',
 translate:'<path d="M3 4h12M8 2v2M5 7c1 4 4 7 8 9m0-12C12 11 8 15 3 17m11 4 4-11 4 11m-6-4h4"/>',
 split:'<path d="M4 4h6v16H4m16-16h-6v16h6M11 8h2m-2 8h2"/>',
 bookmark:'<path d="M6 3h12v19l-6-4-6 4z"/>',
 clock:'<circle cx="12" cy="12" r="9"/><path d="M12 6v6l4 2"/>',
 report:'<path d="M5 3h14v18H5zM9 16v-3m3 3V9m3 7v-5"/>',
 download:'<path d="M12 3v12m-5-5 5 5 5-5M4 17v4h16v-4"/>',
 eye:'<path d="M2 12s4-7 10-7 10 7 10 7-4 7-10 7S2 12 2 12Z"/><circle cx="12" cy="12" r="3"/>',
 info:'<circle cx="12" cy="12" r="9"/><path d="M12 11v6m0-10v.1"/>',
 paw:'<ellipse cx="12" cy="15" rx="5" ry="4"/><circle cx="5" cy="10" r="2"/><circle cx="9" cy="6" r="2"/><circle cx="15" cy="6" r="2"/><circle cx="19" cy="10" r="2"/>'
};
function icon(name){return `<svg class="ico" viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.star}</svg>`;}
function btn(label,action,ic='',cls='',attrs=''){return `<button class="button ${cls}" data-action="${action}" ${attrs}>${ic?icon(ic):''}${label}</button>`;}
function iconBtn(label,action,ic,attrs=''){return `<button class="icon-button" data-action="${action}" aria-label="${E(label)}" title="${E(label)}" ${attrs}>${icon(ic)}</button>`;}
function save(){p.updatedAt=new Date().toISOString();try{localStorage.setItem(STORE,JSON.stringify(p));persistence=true;}catch{if(persistence)toast('此浏览器暂时无法保存进度，可在学习报告中导出备份。');persistence=false;}}
function toast(msg){const el=document.getElementById('toast');el.textContent=msg;el.classList.add('visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('visible'),3400);}
function announce(msg){document.getElementById('live').textContent=msg;}
function chapter(){return L.chapters[p.chapter];}
function sentence(){return chapter().sentences[p.sentence];}
function sourceLabel(c){return `课本图片 ${c.source} · ${c.paragraph}`;}
function header(title,subtitle,chip='课文专属学习'){return `<div class="page-heading"><div><div class="section-eyebrow">LITTLE STEPS, BIG STORIES</div><h1>${title}</h1><p>${subtitle}</p></div><span class="chip green">${icon('book')}${chip}</span></div>`;}
function layout(body){const st=C.stats(p,L);const navs=[['read','compass','阅读探险'],['words','cards','单词宝藏'],['challenge','trophy','侦探挑战'],['retell','mic','我是讲述家'],['extension','museum','博物馆拓展']];return `<div class="layout"><aside class="sidebar"><a class="brand" href="#" data-action="nav" data-view="read" aria-label="故事芽首页"><span class="brand-mark">${icon('cat')}</span><span><strong>故事芽</strong><small>STORY SPROUT</small></span></a><a class="text-btn" href="../book.html?book=4" style="margin-top:18px">← 回到全册课程地图</a><div class="nav-label">我的学习旅程</div><nav class="nav" aria-label="学习导航">${navs.map(([v,ic,t])=>`<button class="${view===v?'active':''}" data-action="nav" data-view="${v}" ${view===v?'aria-current="page"':''}>${icon(ic)}<span>${t}</span></button>`).join('')}</nav><div class="side-bottom"><div class="side-tip">${icon('bulb')}<strong>一小步，也很了不起。</strong>不用一次读完整篇。<br>读懂一句，就往前一步。</div><button class="text-btn" data-action="source">${icon('book')} 查看课本原图</button><a class="text-btn" href="offline.html" download="埃及金猫的秘密_离线学习.html">${icon('download')} 下载离线版</a><div class="side-footer">GROW A LITTLE EVERY DAY</div></div></aside><div class="page"><header class="topbar"><div class="breadcrumbs"><span>我的书架</span><span>／</span><b>博物馆之夜</b></div><div class="top-actions"><span class="top-stars" aria-label="已获得${st.stars}颗关卡星">${icon('star')} ${st.stars}<span class="muted"> / 8</span></span><button class="top-button" data-action="settings" aria-label="声音设置">${icon('settings')}<span>声音设置</span></button><button class="top-button" data-action="report" aria-label="学习报告">${icon('report')}<span>学习报告</span></button><span class="avatar" aria-hidden="true">🌱</span></div></header><main class="content" id="main">${body}<div class="footer-note">依据你提供的 6 张课本图片制作 · 学一点，懂一点，说出来。<br>进度保存在当前浏览器；“会读”由自己确认，发音练习由录音回听。</div></main></div></div>`;}
function render(){const body=({read:renderRead,words:renderWords,challenge:renderChallenge,retell:renderRetell,extension:renderExtension})[view]();document.getElementById('app').innerHTML=layout(body);}
function nav(v){stopSpeech();clearTimeout(timer);quizSession++;if(recorder&&recorder.state==='recording')stopRecord();view=v;render();window.scrollTo({top:0,behavior:'smooth'});save();}
function renderHero(){return `<section class="hero" aria-label="故事介绍"><div class="hero-text"><div class="hero-kicker">${icon('moon')} YOUR NEXT LITTLE ADVENTURE</div><h2>金猫去哪儿了？</h2><div class="english-title">The secret of the Egyptian cat</div><p>和 Cleo 一起，在故事里找到答案。</p><div class="hero-meta">${btn(p.read.length?'继续第 '+(p.chapter+1)+' 关':'开始阅读探险','focus-reader','arrow','primary')}<span>8 个关卡 · 一次一句</span></div></div><img src="hero.svg" class="hero-art" alt="夜晚的博物馆里，一尊金猫坐在展台上，旁边的窗户打开着。原创情境示意插画。"><span class="round-tag">STORY 01</span></section>`;}
function renderRead(){const ch=chapter(),st=C.stats(p,L);const readIn=ch.sentences.filter((_,s)=>p.read.includes(C.key(p.chapter,s))).length;return `${header('今天，做一名小侦探。','不用着急。先听懂一句，再把故事读给自己听。')}${renderHero()}<div class="journey-header"><h3>跟着故事，一步一步走</h3><small>${st.stars} / 8 颗关卡星 · 每一关都可以重读</small></div><div class="journey" aria-label="八个故事关卡">${L.chapters.map((x,c)=>`<button class="stage ${c===p.chapter?'active':''} ${C.chapterComplete(p,L,c)?'complete':''}" data-action="chapter" data-chapter="${c}" aria-label="第${c+1}关 ${E(x.title)}${C.chapterComplete(p,L,c)?' 已完成':''}" ${c===p.chapter?'aria-current="step"':''}><span class="stage-circle">${C.chapterComplete(p,L,c)?icon('star'):String(c+1).padStart(2,'0')}</span><span>${x.title}</span>${C.chapterComplete(p,L,c)?'<span class="tiny-star">✦</span>':''}</button>`).join('')}</div><div class="reading-layout"><div><section class="card reader"><div class="reader-head"><div><h3>第 ${String(p.chapter+1).padStart(2,'0')} 关 · ${ch.title}</h3><small>${ch.en} · ${sourceLabel(ch)}</small></div><div class="reader-mini">${iconBtn('连听本关','listen-chapter','volume')}${iconBtn('查看本关完整原文','chapter-text','book')}</div></div>${checkpoint?renderCheckpoint():renderSentence()}</section><div class="under-reader"><span>不懂的地方，可以多听几遍。</span><button data-action="chapter-text">查看这一关的完整原文</button></div></div><aside class="side-panel"><section class="card mission"><h3>${icon('compass')}这一关的小任务</h3><p>${ch.goal}</p><div class="words">${ch.words.slice(0,4).map(w=>`<button class="word-pill" data-action="word" data-word="${E(w)}">${E(w)}</button>`).join('')}</div></section><div class="clue"><h3>${icon('bulb')}小侦探的线索卡</h3>${p.checkpoints.includes(p.chapter)?`<p>${ch.clue}</p>`:`<p>完成本关的小问题，<br>就能把这条线索收入背包。</p>`}</div><section class="card progress-card"><div class="progress-caption"><span>本关自评会读</span><b>${readIn} / ${ch.sentences.length}</b></div><div class="progress-track"><div class="progress-fill" style="width:${readIn/ch.sentences.length*100}%"></div></div><div class="encourage"><span class="cat-sticker">${icon('cat')}</span><span>${readIn?'你已经往前走了一步。':'从第一句开始就好。'}<br>我会一直陪着你。</span></div></section></aside></div>`;}
function wordMarkup(text){let offset=0;return text.split(/([A-Za-z]+(?:[’'’-][A-Za-z]+)*)/g).map(token=>{const start=offset;offset+=token.length;if(!/^[A-Za-z]/.test(token))return E(token);const raw=token.toLowerCase().replace(/’/g,"'");const base=aliases[raw]||raw;return `<button class="word ${vocabMap.has(base)?'key':''}" data-action="word" data-word="${E(token)}" data-offset="${start}" data-length="${token.length}" aria-label="点读 ${E(token)}">${E(token)}</button>`;}).join('');}
function renderSentence(){const s=sentence(),ch=chapter(),done=p.read.includes(C.key(p.chapter,p.sentence));return `<div class="reader-body"><div class="sentence-label"><span>一句一句读 · ${p.sentence+1} / ${ch.sentences.length}</span><div class="dots" aria-hidden="true">${ch.sentences.map((_,i)=>`<span class="dot ${i===p.sentence?'active':p.read.includes(C.key(p.chapter,i))?'done':''}"></span>`).join('')}</div></div><div class="english" lang="en" id="sentence-text">${phrases?s.parts.map((t,i)=>`<span class="phrase">${E(t)}</span>${i<s.parts.length-1?'<span class="separator">/</span>':''}`).join(''):wordMarkup(s.en)}</div><div class="read-tip">${icon('info')}${phrases?'按意群停顿，先理解每一小块。':'点单词可以听读，紫色下划线词有专属解释。'}</div>${translation?`<div class="translation"><div class="flex" style="justify-content:space-between"><span>${s.zh}</span>${iconBtn('听这句中文','listen-meaning','volume')}</div><div class="note"><strong>这句怎么理解</strong><br>${s.note}</div></div>`:''}<div class="controls">${btn(speaking?'停止朗读':'听这一句',speaking?'stop-speech':'listen',speaking?'stop':'volume','primary','id="listen-button"')}${btn(translation?'收起中文':'看中文', 'translation','translate',translation?'soft':'')}${btn(phrases?'整句阅读':'拆开读','phrases','split',phrases?'soft':'')}<label class="rate"><span>语速</span><select id="rate" aria-label="朗读语速"><option value="0.65" ${p.settings.rate===.65?'selected':''}>0.65 慢速</option><option value="0.8" ${p.settings.rate===.8?'selected':''}>0.8 舒缓</option><option value="1" ${p.settings.rate===1?'selected':''}>1.0 正常</option></select></label></div></div><div class="reader-footer"><button class="text-btn" data-action="prev" ${p.sentence===0&&p.chapter===0?'disabled':''}>${icon('back')} 上一句</button>${btn(p.sentence===ch.sentences.length-1?(done?'再做本关小问题':'会读了，找线索'):(done?'下一句':'会读了，下一句'),'mark-read','arrow','primary')}</div><div class="self-note">按“会读了”记录自评进度；听过与会读分开统计。</div>`;}
function renderCheckpoint(){const q=chapter().quiz;return `<div class="reader-body"><div class="section-eyebrow">ONE LITTLE CHECK</div><h2 style="font-family:Georgia,serif;margin:10px 0;font-size:25px">${q.q}</h2><p class="muted mb">${q.zh}</p><div class="options">${q.options.map((o,i)=>`<button class="option ${chapterFeedback?.choice===i?(chapterFeedback.correct?'correct':'wrong'):''}" data-action="checkpoint-answer" data-index="${i}" ${chapterFeedback?.correct?'disabled':''}><span class="option-letter">${'ABC'[i]}</span><span lang="en">${E(o)}</span></button>`).join('')}</div>${chapterFeedback?`<div class="feedback ${chapterFeedback.correct?'':'wrong'}"><strong>${chapterFeedback.correct?'线索找到了！':'再看看原文，你会找到的。'}</strong><br>${chapterFeedback.correct?q.why:'小提示：'+q.zh}<div class="evidence" lang="en">“${E(q.evidence)}”</div></div>`:''}<div class="game-bottom">${btn('回到句子','back-reading','back')}${chapterFeedback?.correct||p.checkpoints.includes(p.chapter)?btn(p.chapter===7?'去挑战完整故事':'前往下一关','next-chapter','arrow','primary'):btn('听问题','listen-checkpoint','volume','soft')}</div></div>`;}
function renderWords(){const list=L.vocabulary.filter(w=>(wordFilter==='all'||wordFilter==='saved'&&p.saved.includes(w[0])||wordFilter==='review'&&!p.words.includes(w[0])||wordFilter==='learned'&&p.words.includes(w[0]))&&(!search||(w[0]+' '+w[1]).toLowerCase().includes(search.toLowerCase())));return `${header('把生词，变成小宝藏。','先放回故事里理解，再玩一轮配对。','故事词库')}<div class="tabbar"><button class="${wordMode==='cards'?'active':''}" data-action="word-mode" data-mode="cards">${icon('cards')} 词语探索</button><button class="${wordMode==='match'?'active':''}" data-action="word-mode" data-mode="match">${icon('compass')} 词义配对</button></div>${wordMode==='match'?renderMatch():`<div class="vocab-tools"><div class="tabbar" style="margin:0">${[['all','全部词语'],['saved',`我的收藏 ${p.saved.length}`],['review','还要练练'],['learned',`自评已会 ${p.words.length}`]].map(([f,t])=>`<button class="${wordFilter===f?'active':''}" data-action="word-filter" data-filter="${f}">${t}</button>`).join('')}</div><input class="input search" id="vocab-search" placeholder="找一个英文单词或中文意思…" aria-label="搜索词语" value="${E(search)}"></div><div id="word-list" class="word-grid">${renderWordCards(list)}</div>`}`;}
function renderWordCards(list){return list.length?list.map(w=>`<article class="card word-card ${p.words.includes(w[0])?'learned':''}"><span class="chip ${p.words.includes(w[0])?'green':''}">${p.words.includes(w[0])?'自评已会':w[2]}</span><div class="word-top mt"><h3 lang="en">${w[0]}</h3>${iconBtn('朗读 '+w[0],'vocab-speak','volume',`data-word="${E(w[0])}"`)}</div><div class="definition">${w[1]}</div><div class="context">${w[3]}</div><div class="word-actions"><button data-action="save-word" data-word="${E(w[0])}" class="${p.saved.includes(w[0])?'selected':''}">${icon('bookmark')}${p.saved.includes(w[0])?'已收藏':'收藏'}</button><button data-action="learn-word" data-word="${E(w[0])}" class="${p.words.includes(w[0])?'selected':''}">${icon('check')}${p.words.includes(w[0])?'还想复习':'这个我会了'}</button><button data-action="word-context" data-word="${E(w[0])}" aria-label="在原文中查看 ${E(w[0])}">${icon('book')}</button></div></article>`).join(''):`<div class="card empty-state full-width"><h3>这里还没有词卡</h3><p>试试其他筛选条件，或回到故事里点一个单词。</p></div>`;}
function newMatch(){const review=L.vocabulary.filter(w=>!p.match.includes(w[0]));matchWords=C.shuffle(review.length>=5?review:L.vocabulary).slice(0,5);matchRight=C.shuffle(matchWords.map((_,i)=>i));matchDone=[];matchLeft=null;matchSelection=null;}
function renderMatch(){if(!matchWords.length)newMatch();return `<section class="card game-card"><div class="game-meta"><span>WORD MATCH · 先点英文，再找中文</span><span>${matchDone.length} / 5 组</span></div><h2 class="mb">给词语找到它的意思</h2><p class="muted mb">点选一对。答错可以再试，不扣分。</p><div class="match-board"><div class="match-column">${matchWords.map((w,i)=>`<button class="match-item ${matchLeft===i?'chosen':''} ${matchDone.includes(i)?'matched':''}" data-action="match-left" data-index="${i}" ${matchDone.includes(i)?'disabled':''} lang="en">${E(w[0])}${matchDone.includes(i)?' ✓':''}</button>`).join('')}</div><div class="match-column">${matchRight.map(i=>`<button class="match-item zh ${matchSelection===i?'chosen':''} ${matchDone.includes(i)?'matched':''}" data-action="match-right" data-index="${i}" ${matchDone.includes(i)?'disabled':''}>${E(matchWords[i][1])}</button>`).join('')}</div></div>${matchDone.length===5?'<div class="feedback">五组配对完成！这些词已记入本次练习记录。</div>':''}<div class="game-bottom"><span class="tiny muted">每一轮 5 组 · 随时重听</span>${btn('换一组词语','new-match','repeat','primary')}</div></section>`;}
function renderChallenge(){return `${header('证据，都藏在故事里。','先读题，再找原句。答错时，我们一起沿着线索回去。','故事理解')}<div class="tabbar">${[['quiz','理解小侦探'],['order','故事时间线'],['build','句子拼拼乐']].map(([v,t])=>`<button class="${challenge===v?'active':''}" data-action="challenge-tab" data-tab="${v}">${t}</button>`).join('')}</div>${challenge==='quiz'?renderQuiz():challenge==='order'?renderOrder():renderBuilder()}`;}
function renderQuiz(){if(quizDone)return `<section class="card success-view"><div class="badge-large finish-star">${icon('trophy')}</div><h2>你走完了这一轮故事挑战！</h2><p>累计答对 ${C.stats(p,L).quizCorrect} / ${questions.length} 道题。<br>带着原文证据，说说你发现的秘密吧。</p><div class="flex" style="justify-content:center">${btn('再挑战一次','restart-quiz','repeat','soft')}${btn('去讲故事','nav','mic','primary','data-view="retell"')}</div></section>`;const q=questions[qIndex];return `<section class="card game-card"><div class="game-meta"><span>DETECTIVE CHALLENGE · ${qIndex+1} / ${questions.length}</span><label class="flex"><input type="checkbox" id="auto-next" ${p.settings.autoNext?'checked':''}>答对后自动前进</label></div><div class="question" lang="en">${E(q.q)}</div><p class="question-zh">${E(q.zh)}</p><div class="options">${q.options.map((o,i)=>`<button class="option ${qFeedback?.choice===i?(qFeedback.correct?'correct':'wrong'):''}" data-action="quiz-answer" data-index="${i}" ${qFeedback?.correct?'disabled':''}><span class="option-letter">${'ABC'[i]}</span><span lang="en">${E(o)}</span></button>`).join('')}</div>${qHint?`<div class="hint-panel">去第 ${q.chapter+1} 关找这条证据：<div class="en">“${E(q.evidence)}”</div>${btn('回原文看看','jump-evidence','book','','data-chapter="'+q.chapter+'" data-sentence="'+q.sentence+'"')}</div>`:''}${qFeedback?`<div class="feedback ${qFeedback.correct?'':'wrong'}"><strong>${qFeedback.correct?'找对了！':'没关系，再找一条线索。'}</strong><br>${qFeedback.correct?q.why:'可以点“找原文线索”，看清楚人物、动作和时间。'}${qFeedback.correct?'<br><small>'+(p.settings.autoNext?'6秒后自动进入下一题；也可以关闭自动前进。':'读完解析后，点“下一题”继续。')+'</small>':''}</div>`:''}<div class="game-bottom"><div class="flex">${btn('听题目','listen-question','volume','soft')}${btn(qHint?'收起线索':'找原文线索','quiz-hint','search')}</div>${qFeedback?.correct?btn('下一题','next-question','arrow','primary'):btn('先跳过','next-question','arrow')}</div></section>`;}
function renderOrder(){return `<section class="card game-card"><div class="game-meta"><span>STORY TIMELINE · ${orderAnswer.length} / 6</span><span>从最早发生的事开始</span></div><h2 class="mb">把故事排回正确的顺序</h2><p class="muted mb">依次点击下面的事件卡。点上面的卡片可以撤回。</p><div class="order-answer">${orderAnswer.length?orderAnswer.map((n,i)=>`<button class="order-item" data-action="order-remove" data-index="${i}" aria-label="移除第${i+1}项"><span class="order-number">${i+1}</span><span class="order-text">${L.order[n].en}<small>${L.order[n].zh}</small></span></button>`).join(''):'<span class="hint">故事的第一件事是什么？</span>'}</div><div class="order-pool">${orderPool.map(n=>`<button class="order-item ${orderAnswer.includes(n)?'used':''}" data-action="order-add" data-index="${n}" ${orderAnswer.includes(n)?'disabled':''}><span class="order-number">+</span><span class="order-text">${L.order[n].en}<small>${L.order[n].zh}</small></span></button>`).join('')}</div>${orderFeedback?`<div class="feedback ${orderFeedback==='correct'?'':'wrong'}">${orderFeedback==='correct'?'时间线接起来了！现在可以按照这个顺序复述整个故事。':'再检查一下：先参加聚会，再遇到路上的猫；爸爸发现失踪后，Cleo 才开始调查。'}</div>`:''}<div class="game-bottom">${btn('重新排列','order-reset','repeat')}${btn('检查时间线','order-check','check','primary',orderAnswer.length===6?'':'disabled')}</div><p class="source-tag">事件卡是根据原文制作的简短概括，并非逐字原句。</p></section>`;}
function renderBuilder(){const b=L.builders[builder];return `<section class="card game-card"><div class="game-meta"><span>SENTENCE PUZZLE · ${builder+1} / ${L.builders.length}</span><span>来自课文原句</span></div><h2 class="mb">用小积木，搭一个完整句子</h2><p class="muted mb">${b.zh}</p><div class="order-answer">${builderAnswer.length?builderAnswer.map((v,i)=>`<button class="word-token" data-action="builder-remove" data-index="${i}">${E(b.parts[v])}</button>`).join(''):'<span class="hint">按照英文语序，依次点击词块。</span>'}</div><div class="token-pool">${builderPool.map(i=>`<button class="word-token" data-action="builder-add" data-index="${i}" ${builderAnswer.includes(i)?'disabled':''}>${E(b.parts[i])}</button>`).join('')}</div>${builderFeedback?`<div class="feedback ${builderFeedback==='correct'?'':'wrong'}">${builderFeedback==='correct'?'拼对了！听一遍，再自己说一遍。':'顺序还需要调整。先听原句，找谁在做什么，再找时间或地点。'}</div>`:''}<div class="game-bottom">${btn('听原句','builder-listen','volume','soft')}${builderFeedback==='correct'?btn(builder===L.builders.length-1?'从第一句再练':'下一个句子','builder-next','arrow','primary'):btn('检查句子','builder-check','check','primary',builderAnswer.length===b.parts.length?'':'disabled')}</div></section>`;}
function renderRetell(){return `${header('现在，轮到你讲故事了。','先用中文讲清意思，再试着用英文说。提示可以随时打开。','理解 → 表达')}<div class="banner">${icon('mic')}<span><strong>讲故事不是背课文。</strong> 说清人物、问题、调查和结局，就很棒。</span></div><div class="flex">${btn(retellHints?'收起示范，自己说':'打开复述示范','retell-hints','eye','soft')}${btn('听完整复述示范','retell-listen','volume')}<span class="tiny muted">下面是简化复述示范，已与原文区分。</span></div><div class="retell-grid">${L.retelling.map((r,i)=>`<section class="card retell-card"><h3><span>${String(i+1).padStart(2,'0')} · ${r.label}</span>${iconBtn('朗读这一段示范','retell-line','volume',`data-index="${i}"`)}</h3>${retellHints?`<div class="prompt" lang="en">${r.en}</div><p>${r.zh}</p>`:'<div class="prompt">试着自己说一说…</div>'}<div class="hint">${r.hint}</div></section>`).join('')}</div><div class="story-logic"><h3>${icon('bulb')}结尾的秘密，要有线索支持</h3>【原文】柜子先空了，后来金猫回到了柜子里。<br>【原文】Cleo 说：“I hope you had some fun outside.”<br>【推断】（金猫消失又返回 + Cleo 提到在外面玩 ⇒ 故事暗示金猫曾自己外出。）<br>【开放想象】去钓鱼、去找朋友，是课后可以创作的情节。原文没有交代它具体做了什么，也没有解释报警器为什么没有响。</div><section class="card recorder"><h3>留下一段自己的声音</h3><p>点击录音后，浏览器会请求麦克风权限。录音仅在本页保留，可回听或下载；不会自动上传，也不生成发音分数。单次最长 3 分钟。</p><div id="record-ui">${renderRecordControls()}</div><label for="retell-draft" class="muted tiny">也可以把你的复述写下来（中文或英文都可以）</label><textarea id="retell-draft" class="draft" placeholder="Mr Benson was… / 这个故事讲的是……">${E(p.draft)}</textarea><div class="checklist">${['我说清了人物和地点','我说清了发生的问题','我说清了 Cleo 的调查','我用线索解释了结尾'].map((t,i)=>`<label><input type="checkbox" data-check="${i}" ${p.retellChecks.includes(i)?'checked':''}>${t}</label>`).join('')}</div><div class="mt">${btn('保存我的复述','save-draft','check','primary')}${btn('查看学习报告','report','report')}</div></section>`;}
function renderRecordControls(){const active=recorder?.state==='recording';return `<div class="flex mb">${btn(active?'停止录音':recordBusy?'正在请求麦克风…':recordURL?'重新录一段':'开始录音',active?'record-stop':'record-start',active?'stop':'mic',active?'danger recording':'primary',recordBusy?'disabled':'')}${recordURL?`<a class="button soft" href="${recordURL}" download="我的金猫故事.${recordBlob?.type.includes('mp4')?'m4a':recordBlob?.type.includes('ogg')?'ogg':'webm'}">${icon('download')}下载录音</a>`:''}<span class="tiny muted" id="record-status">${active?'正在录音，读完后点“停止录音”。':'可以先听示范，再录自己的版本。'}</span></div>${recordURL?`<audio controls src="${recordURL}" aria-label="回听我的录音"></audio>`:''}`;}
function renderExtension(){return `${header('走进更大的博物馆世界。','完成主故事后，再来阅读、扮演和创作。','覆盖其余 4 张图片')}<div class="tabbar">${[['museums','阅读与归类'],['role','猫咪小剧场'],['advert','我的博物馆广告'],['capsule','时间胶囊']].map(([v,t])=>`<button class="${extension===v?'active':''}" data-action="extension-tab" data-tab="${v}">${t}</button>`).join('')}</div>${extension==='museums'?renderMuseums():extension==='role'?renderRole():extension==='advert'?renderAdvert():renderCapsule()}`;}
function renderMuseums(){return `<div class="notice">阅读区保留教材的原句和数字，回答“根据课文”的题目时以原文为依据。年代和展陈现状另见核对说明。</div>${L.museumTexts.map((m,mi)=>`<section class="card extension-card"><span class="chip">${m.tag}</span><h3 class="mt">${m.title}</h3><p class="subtitle">${m.zh} · 课本图片 3 / 第18页</p>${m.sentences.map(([en,zh],si)=>`<div class="extension-row"><div><p class="en" lang="en">${E(en)}</p><details><summary>展开中文讲解</summary><p class="zh">${zh}</p></details></div>${iconBtn('朗读这一句','museum-listen','volume',`data-museum="${mi}" data-index="${si}"`)}</div>`).join('')}</section>`).join('')}<details class="notice"><summary>家长阅读 · 教材年代与展陈信息核对</summary><p>① 教材写图坦卡蒙生活在约 2,700 年前。埃及旅游和文物部（Ministry of Tourism and Antiquities）的官方页面将其统治年代列为约公元前 1336—1327 年。以 2026 年计算，是三千三百多年前。教材原句保留，知识讲解指出这处年代错误。</p><p>② 埃及国家文明博物馆（National Museum of Egyptian Civilization）2021年8月5日公告记录：22具皇家木乃伊于2021年4月3日从解放广场埃及博物馆迁入该馆。因此，教材中的“27具”与展陈位置不能直接作为2026年的参观信息。</p><p>依据：<a href="https://egymonuments.gov.eg/monuments/tomb-of-tutankhamun/" target="_blank" rel="noopener noreferrer">埃及旅游和文物部：Tomb of Tutankhamun（核对日期：2026-10-19；页面未注明发布日期）</a>；<a href="https://nmec.gov.eg/issuance-of-a-commemorative-coin-to-commemorate-the-transfer-of-the-royal-mummies-to-the-national-museum-of-egyptian-civilization/" target="_blank" rel="noopener noreferrer">埃及国家文明博物馆：2021年迁移纪念公告</a>。</p><p>其他馆藏数量、排序和具体陈列位置在此仅作为教材阅读内容。[!!! 事实断层：资料不足，无法确认] 这些信息的2026年现状。</p></details><section class="card extension-card"><h3>给展品找到它的博物馆</h3><p class="subtitle">对应第18页图片配对题 · 按教材内容选择 A 或 B</p>${[['木乃伊','B'],['萨波特克面具','A'],['图坦卡蒙黄金面具','B'],['太阳石','A']].map(([t,a],i)=>`<div class="extension-row"><div><strong>${i+1}. ${t}</strong><p class="zh">${museumMatches[i]?museumMatches[i]===a?'✓ 根据课文，归类正确。':'再查一查课文 A、B 的展品名称。':''}</p></div><div class="flex"><button class="button ${museumMatches[i]==='A'?'soft':''}" data-action="museum-match" data-index="${i}" data-value="A">A</button><button class="button ${museumMatches[i]==='B'?'soft':''}" data-action="museum-match" data-index="${i}" data-value="B">B</button></div></div>`).join('')}<p class="source-tag">A：墨西哥国家人类学博物馆；B：课文中的开罗埃及博物馆。</p></section><section class="card extension-card"><h3>读完后，完成博物馆信息表</h3><p class="subtitle">对应第19页 · 先自己说答案，再展开对照。</p><details><summary class="muted">展开参考答案</summary><div class="table-wrap"><table><thead><tr><th>What to find</th><th>A · Mexico City</th><th>B · Cairo</th></tr></thead><tbody>${L.museumTable.map(r=>`<tr>${r.map(v=>`<td>${E(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div></details></section>`;}
function renderRole(){const r=L.roles[roleIndex];return `<section class="card extension-card"><span class="chip gold">ROLE PLAY · 第20页</span><h3 class="mt">A visit from the cat</h3><p class="subtitle">选择你的角色，和家长轮流说。下面是新编练习台词，其中朋友、夜间活动和喜爱展品属于创作示例。</p><div class="role-switch">${btn('我当来访的朋友','role-select','mic',role==='friend'?'primary':'','data-role="friend"')}${btn('我当博物馆金猫','role-select','cat',role==='cat'?'primary':'','data-role="cat"')}</div><div class="game-meta"><span>对话 ${roleIndex+1} / ${L.roles.length}</span><span>你的角色：${role==='friend'?'Friend':'Cat'}</span></div><div class="role-card"><div class="role-label">${role==='friend'?'轮到你提问 · FRIEND':'先听朋友问 · FRIEND'}</div><div class="line" lang="en">${r.q}</div><p>${r.qzh}</p>${btn('听问题','role-listen','volume','soft','data-line="q"')}</div><div class="role-card" style="background:#fcf3dd"><div class="role-label">${role==='cat'?'轮到你回答 · CAT':'听听金猫的示范 · CAT'}</div><div class="line" lang="en">${r.a}</div><p>${r.azh}</p>${btn('听示范回答','role-listen','volume','soft','data-line="a"')}</div><div class="game-bottom"><span class="tiny muted">把范例中的朋友或展品换成你自己的想法。</span>${btn(roleIndex===3?'再演一遍':'下一轮对话','role-next','arrow','primary')}</div></section>`;}
function advertText(){const a=p.advert;const name=a.name||'My Wonderful Museum',topic=a.topic||'the history of our town',exhibit=a.exhibit||'a beautiful collection of old photos',hours=a.hours||'from 9 a.m. to 4 p.m., Monday to Friday',extra=a.extra||'a café and a bookshop';return {title:`Come and visit ${name}!`,text:`Discover ${topic}. You can see ${exhibit}. We are open ${hours}. There is also ${extra}. Come and explore!`};}
function renderAdvert(){const a=p.advert,ad=advertText();return `<section class="card extension-card"><span class="chip gold">MAKE AN ADVERT · 第21页</span><h3 class="mt">从“interesting”到更具体的表达</h3><p class="subtitle">课本广告反复用了 interesting。练习时，可以用具体信息和更丰富的形容词，让读者知道看什么、何时去。下面生成的是练习广告，博物馆及开放信息由你填写。</p><details><summary class="muted">阅读课本原广告（逐句听读与中文）</summary>${L.advert.map(([en,zh],i)=>`<div class="extension-row"><div><p class="en">${E(en)}</p><p class="zh">${zh}</p></div>${iconBtn('朗读','ad-source-listen','volume',`data-index="${i}"`)}</div>`).join('')}</details><div class="field-grid mt">${[['name','博物馆名称','My Wonderful Museum'],['topic','可以学到什么（英文）','the history of our town'],['exhibit','有什么展品（英文）','a beautiful collection of old photos'],['hours','开放时间（英文）','from 9 a.m. to 4 p.m., Monday to Friday'],['extra','其他设施（英文）','a café and a bookshop']].map(([id,label,placeholder])=>`<label>${label}<input class="input" id="ad-${id}" data-ad="${id}" value="${E(a[id]||'')}" placeholder="${placeholder}" maxlength="200"></label>`).join('')}</div><div id="ad-preview" class="ad-preview"><h3>${E(ad.title)}</h3><p>${E(ad.text)}</p></div><div class="flex mt">${btn('听我的广告','ad-listen','volume','primary')}${btn('复制广告','ad-copy','book')}${btn('保存文字文件','ad-download','download')}</div></section>`;}
function renderCapsule(){const items=[['a mobile phone','手机'],['a games console','游戏机'],['a rucksack','背包'],['a digital camera','数码相机'],['a book','书'],['a toy','玩具'],['a postcard','明信片'],['a watch','手表']];return `<section class="card extension-card"><span class="chip gold">TIME CAPSULE · 第19页</span><h3 class="mt">把今天，装进时间胶囊</h3><p class="subtitle">课文活动：选择四样物品，让未来的人了解今天的生活。前四项来自教材，后四项是练习补充。</p><div class="capsule-grid">${items.map(([en,zh])=>`<button class="capsule-item ${p.capsule.includes(en)?'selected':''}" data-action="capsule" data-value="${en}">${E(en)}<br><small class="muted">${zh}</small>${p.capsule.includes(en)?' ✓':''}</button>`).join('')}</div><div class="ad-preview"><h3>My time capsule</h3><p>${p.capsule.length?'I want to put '+E(p.capsule.join(', '))+' in my time capsule.':'Choose four things for your time capsule.'}</p></div><div class="game-bottom"><span class="muted">已选择 ${p.capsule.length} / 4 样</span>${btn('听我的句子','capsule-listen','volume','primary',p.capsule.length?'':'disabled')}</div><p class="source-tag">还可以说：I chose it because ...（我选择它，因为……）。</p></section>`;}
function openModal(title,html,cls=''){dialogReturnFocus=document.activeElement;const d=document.getElementById('modal');d.className=cls;d.innerHTML=`<div class="modal-top"><h2 id="modal-title">${title}</h2>${iconBtn('关闭窗口','close-modal','close')}</div>${html}`;if(!d.open)d.showModal();}
function closeModal(){stopSpeech();document.getElementById('modal').close();if(dialogReturnFocus?.isConnected)dialogReturnFocus.focus();}
function showWord(raw){stopSpeech();const clean=raw.toLowerCase().replace(/’/g,"'");const word=vocabMap.get(aliases[clean]||clean);openModal(E(raw),`<div class="meaning">${word?word[1]:'单词点读'}</div><div class="word-note">${word?word[3]:'这个词未列入本课重点词库。可以先听发音，再结合本句中文理解它的作用。'}</div><div class="flex">${btn('听这个词','vocab-speak','volume','primary',`data-word="${E(word?.[0]||raw)}"`)}${word?btn(p.saved.includes(word[0])?'已收藏':'加入词语背包','modal-save-word','bookmark','',`data-word="${E(word[0])}"`):''}</div>`, 'word-modal');}
function showChapterText(){const ch=chapter();openModal(`${ch.title} · 完整原文`,`<div class="source-full"><p class="muted tiny">${sourceLabel(ch)} · 英文逐句转录，中文为学习讲解。</p><div class="para" lang="en">${ch.sentences.map(s=>E(s.en)).join(' ')}</div><details open><summary class="muted">中文理解</summary><div class="trans">${ch.sentences.map(s=>s.zh).join('')}</div></details><div class="flex mt">${btn('听英文','modal-chapter-speak','volume','primary')}${btn('听中文讲解','modal-chinese-speak','volume','soft')}</div><p class="source-tag">${ch.clue}</p></div>`);}
function showSource(index=-1){openModal('课本原文与图片',`<div class="source-pager">${btn('完整故事文本','source-text','book',index===-1?'primary':'')}${L.sourcePages.map(([t],i)=>btn(t,'source-page','',index===i?'primary':'',`data-index="${i}"`)).join('')}</div>${index===-1?`<div class="source-full"><h2>${L.title}</h2><p class="source-tag">转录依据：2026-10-19 上传的第1、2张课本照片。教材书名、版本和出版年未出现在这些图片中。</p>${L.chapters.map((ch,c)=>`<h3>${String(c+1).padStart(2,'0')} · ${ch.title}</h3><div class="para" lang="en">${ch.sentences.map(s=>E(s.en)).join(' ')}</div><details><summary class="muted tiny">展开这一段中文</summary><div class="trans">${ch.sentences.map(s=>s.zh).join('')}</div></details>`).join('')}${btn('打印阅读稿','print','report')}</div>`:`<img class="source-photo" src="${L.sourcePages[index][1]}" alt="${E(L.sourcePages[index][0])}原始照片">`}`);}
function availableVoices(){return 'speechSynthesis' in window?window.speechSynthesis.getVoices():[];}
function voiceOptions(lang,selected){const voices=availableVoices().filter(v=>v.lang.toLowerCase().startsWith(lang));return '<option value="">自动选择'+(lang==='en'?'英语':'中文')+'声音</option>'+voices.map(v=>`<option value="${E(v.voiceURI)}" ${v.voiceURI===selected?'selected':''}>${E(v.name)} · ${E(v.lang)}</option>`).join('');}
function showSettings(){openModal('让声音适合你',`<div class="settings-group"><label for="voice-select">英语声音</label><select class="input" id="voice-select">${voiceOptions('en',p.settings.voice)}</select></div><div class="settings-group"><label for="zh-voice-select">中文讲解声音</label><select class="input" id="zh-voice-select">${voiceOptions('zh',p.settings.chineseVoice)}</select></div><div class="settings-group"><label for="setting-rate">英文朗读速度</label><select class="input" id="setting-rate">${[.65,.8,1].map(r=>`<option value="${r}" ${p.settings.rate===r?'selected':''}>${r} × ${r===.65?'慢慢读':r===.8?'舒缓':'正常'}</option>`).join('')}</select></div><label class="flex muted mb"><input type="checkbox" id="repeat-setting" ${p.settings.repeat?'checked':''}>每次“听这一句”读两遍</label><div class="flex">${btn('试一下英语声音','voice-test','volume','primary')}${btn('刷新声音列表','refresh-voices','repeat')}${btn('保存并返回','close-modal','check')}</div><div class="notice">声音由浏览器和设备提供。若没有声音：检查设备音量，在浏览器中打开此页面，并确认系统已安装英语语音包。可切换声音后重试。离线可用性取决于所选系统声音。</div>`);}
function reportObject(){return {title:L.title,generatedAt:new Date().toISOString(),summary:C.stats(p,L),activeMinutes:Math.round(p.activeSeconds/60),progress:p,note:'会读与会词是自评；题目记录区分首次正确与重试后正确。录音未自动评分。'};}
function showReport(){const st=C.stats(p,L);openModal('我的阅读探险记录',`<p class="muted">${L.title}</p><div class="stats"><div class="stat"><strong>${st.stars}/8</strong><small>读句 + 找线索完成关卡</small></div><div class="stat"><strong>${st.read}/${st.total}</strong><small>自评会读的短句单元</small></div><div class="stat"><strong>${st.quizCorrect}/${questions.length}</strong><small>挑战题累计答对</small></div><div class="stat"><strong>${p.words.length}</strong><small>自评已会词语</small></div></div><div class="report-list">朗读完整播放：${st.heard} / ${st.total} 个短句单元<br>挑战题首次正确：${st.firstCorrect} / ${st.quizAttempted} 道已作答题<br>故事排序：${p.ordered?'已排对':'还没完成'}；句子拼接：${p.builders.length} / ${L.builders.length}<br>词义配对累计：${p.match.length} 个词；复述自查：${p.retellChecks.length} / 4<br>当前设备页面活跃用时：${Math.floor(p.activeSeconds/60)} 分钟<br>${persistence?'进度已在当前浏览器保存。':'当前环境不支持持久保存，请导出备份。'}</div><div class="notice">关卡星代表“所有句子自评会读 + 本关题答对”。本页没有自动发音评测，也不以按钮点击证明已经掌握。建议家长听一次复述，再核对故事是否讲清楚。</div><div class="flex">${btn('导出进度备份','export-progress','download','primary')}${btn('恢复进度备份','import-progress','book')}${btn('打印记录','print','report')}<a class="button" href="offline.html" download="埃及金猫的秘密_离线学习.html">${icon('download')}离线学习版</a></div><input type="file" id="progress-file" accept="application/json,.json" class="hidden"><div class="mt">${btn('重新开始学习','reset-dialog','repeat')}</div>`);}
function updateListenButton(){const b=document.getElementById('listen-button');if(b){b.dataset.action=speaking?'stop-speech':'listen';b.innerHTML=icon(speaking?'stop':'volume')+(speaking?'停止朗读':'听这一句');}}
function stopSpeech(){speakToken++;if('speechSynthesis' in window)window.speechSynthesis.cancel();speaking=false;currentUtterance=null;document.querySelectorAll('.word.speaking').forEach(e=>e.classList.remove('speaking'));updateListenButton();}
function speechVoice(lang){const list=availableVoices(),wanted=lang.startsWith('zh')?p.settings.chineseVoice:p.settings.voice;return list.find(v=>v.voiceURI===wanted&&v.lang.startsWith(lang.slice(0,2)))||list.find(v=>v.lang===lang)||list.find(v=>v.lang.toLowerCase().startsWith(lang.slice(0,2)))||null;}
function speakSequence(items,options={}){stopSpeech();if(!('speechSynthesis' in window)||!('SpeechSynthesisUtterance' in window)){toast('此浏览器暂不支持朗读，请用支持系统语音的浏览器打开。');return;}if(recorder?.state==='recording'){toast('先停止录音，再听示范，避免把示范录进去。');return;}const token=speakToken,lang=options.lang||'en-GB';let at=0;function next(){if(token!==speakToken)return;if(at>=items.length){speaking=false;currentUtterance=null;updateListenButton();announce('朗读完成');return;}const item=items[at++];if(item.chapter!==undefined&&options.follow){p.chapter=item.chapter;p.sentence=item.sentence;checkpoint=false;render();}const u=new SpeechSynthesisUtterance(item.text);u.lang=lang;u.rate=options.rate||(lang.startsWith('zh')?1:p.settings.rate);u.pitch=1;const voice=speechVoice(lang);if(voice)u.voice=voice;currentUtterance=u;u.onstart=()=>{if(token!==speakToken)return;speaking=true;updateListenButton();};u.onboundary=event=>{if(token!==speakToken||!options.highlight||phrases)return;document.querySelectorAll('.word.speaking').forEach(e=>e.classList.remove('speaking'));for(const el of document.querySelectorAll('#sentence-text .word')){const start=Number(el.dataset.offset),end=start+Number(el.dataset.length);if(event.charIndex>=start&&event.charIndex<end){el.classList.add('speaking');break;}}};u.onend=()=>{if(token!==speakToken)return;document.querySelectorAll('.word.speaking').forEach(e=>e.classList.remove('speaking'));if(item.chapter!==undefined){C.add(p.heard,C.key(item.chapter,item.sentence));save();}next();};u.onerror=event=>{if(token!==speakToken||event.error==='canceled'||event.error==='interrupted')return;speaking=false;updateListenButton();toast('朗读没有成功。请在“声音设置”中选择英语声音后重试。');};window.speechSynthesis.speak(u);}next();}
function speak(text,lang='en-GB'){speakSequence([{text}],{lang});}
function listenCurrent(){const item={text:sentence().en,chapter:p.chapter,sentence:p.sentence};speakSequence(p.settings.repeat?[item,item]:[item],{highlight:true});}
function pronounceWord(word){if(word.toLowerCase()==='read'){speak('I read a book yesterday.');toast('read 在这里是过去式 /red/，用例句帮助听辨。');}else if(word.toLowerCase()==='close'){speak('That was close! Close the window.');toast('依次朗读“好险”和“关窗”，听两个 close 的区别。');}else speak(word);}
function markRead(){stopSpeech();C.add(p.read,C.key(p.chapter,p.sentence));if(p.sentence<chapter().sentences.length-1){p.sentence++;translation=false;}else{checkpoint=true;chapterFeedback=null;}save();render();announce(checkpoint?'进入本关线索问题':'下一句');}
function gotoChapter(c,s=0){stopSpeech();p.chapter=Math.max(0,Math.min(c,L.chapters.length-1));p.sentence=Math.max(0,Math.min(s,chapter().sentences.length-1));checkpoint=false;chapterFeedback=null;translation=false;view='read';save();render();}
function nextQuestion(){clearTimeout(timer);stopSpeech();qFeedback=null;qHint=false;if(qIndex<questions.length-1)qIndex++;else quizDone=true;render();}
function answerQuiz(i){if(qFeedback?.correct)return;const correct=i===questions[qIndex].answer;C.answer(p,'q'+qIndex,correct);qFeedback={choice:i,correct};save();render();announce(correct?'答对了':'再试一次');if(correct&&p.settings.autoNext){const session=quizSession;timer=setTimeout(()=>{if(session===quizSession&&view==='challenge'&&challenge==='quiz')nextQuestion();},6000);}}
function wordContext(word){const lower=word.toLowerCase(),forms=[lower,...Object.keys(aliases).filter(k=>aliases[k]===lower)];for(let c=0;c<L.chapters.length;c++)for(let s=0;s<L.chapters[c].sentences.length;s++){const text=L.chapters[c].sentences[s].en.toLowerCase();if(forms.some(w=>new RegExp('\\b'+w.replace(/[.*+?^${}()|[\]\\]/g,'\\$&')+'\\b').test(text))){if(document.getElementById('modal').open)closeModal();gotoChapter(c,s);translation=true;render();return;}}toast('这个词的说明已在词卡中，可回到相应章节练习。');}
function resetBuilder(i){builder=i;builderPool=C.shuffle(L.builders[i].parts.map((_,n)=>n));builderAnswer=[];builderFeedback='';}
function download(name,content,type='application/json'){const url=URL.createObjectURL(new Blob([content],{type}));const a=document.createElement('a');a.href=url;a.download=name;document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),3000);}
async function startRecord(){stopSpeech();if(recordBusy||recorder?.state==='recording')return;if(!navigator.mediaDevices?.getUserMedia||!window.MediaRecorder){toast('当前浏览器不支持录音，可直接对家长复述，或用设备录音工具回听。');return;}recordBusy=true;refreshRecord();let stream;try{stream=await navigator.mediaDevices.getUserMedia({audio:true});if(view!=='retell'){stream.getTracks().forEach(t=>t.stop());recordBusy=false;return;}recordStream=stream;recordChunks=[];const mime=['audio/webm;codecs=opus','audio/mp4','audio/webm'].find(x=>MediaRecorder.isTypeSupported(x));recorder=new MediaRecorder(stream,mime?{mimeType:mime}:undefined);recorder.ondataavailable=e=>{if(e.data.size)recordChunks.push(e.data);};recorder.onstop=()=>{clearTimeout(recordTimeout);stream.getTracks().forEach(t=>t.stop());recordStream=null;if(recordURL)URL.revokeObjectURL(recordURL);recordBlob=new Blob(recordChunks,{type:recorder.mimeType||'audio/webm'});recordURL=URL.createObjectURL(recordBlob);refreshRecord();};recorder.onerror=()=>{stream.getTracks().forEach(t=>t.stop());recordStream=null;toast('录音中断，请检查麦克风后重试。');refreshRecord();};recorder.start();recordStart=Date.now();recordTimeout=setTimeout(()=>{stopRecord();toast('已保存这段录音，可以回听或再录一段。');},180000);recordBusy=false;refreshRecord();}catch{stream?.getTracks().forEach(t=>t.stop());recordBusy=false;toast('未能打开麦克风。检查浏览器权限后再试，也可以直接练习口头复述。');refreshRecord();}}
function stopRecord(){if(recorder?.state==='recording')recorder.stop();clearTimeout(recordTimeout);}
function refreshRecord(){const el=document.getElementById('record-ui');if(el)el.innerHTML=renderRecordControls();}
function updateAdPreview(){const el=document.getElementById('ad-preview'),ad=advertText();if(el)el.innerHTML=`<h3>${E(ad.title)}</h3><p>${E(ad.text)}</p>`;}
document.addEventListener('click',async event=>{const b=event.target.closest('[data-action]');if(!b||b.disabled)return;lastInteraction=Date.now();event.preventDefault();const a=b.dataset.action,i=Number(b.dataset.index);switch(a){
case 'nav':nav(b.dataset.view);break;
case 'focus-reader':document.querySelector('.reader').scrollIntoView({behavior:'smooth',block:'start'});break;
case 'chapter':gotoChapter(Number(b.dataset.chapter));break;
case 'listen':listenCurrent();break;
case 'listen-meaning':speak(sentence().zh,'zh-CN');break;
case 'stop-speech':stopSpeech();break;
case 'listen-chapter':speakSequence(chapter().sentences.map((s,i)=>({text:s.en,chapter:p.chapter,sentence:i})),{follow:true,highlight:true});break;
case 'translation':translation=!translation;stopSpeech();render();break;
case 'phrases':phrases=!phrases;stopSpeech();render();break;
case 'prev':if(p.sentence>0)gotoChapter(p.chapter,p.sentence-1);else if(p.chapter>0)gotoChapter(p.chapter-1,L.chapters[p.chapter-1].sentences.length-1);break;
case 'mark-read':markRead();break;
case 'checkpoint-answer':{const correct=i===chapter().quiz.answer;chapterFeedback={choice:i,correct};if(correct){C.add(p.checkpoints,p.chapter);toast(C.chapterComplete(p,L,p.chapter)?'获得一颗关卡星！你读完了，也找到了证据。':'找到线索了！把本关句子读完，还能获得关卡星。');}save();render();break;}
case 'back-reading':checkpoint=false;render();break;
case 'next-chapter':if(p.chapter<7)gotoChapter(p.chapter+1);else nav('challenge');break;
case 'listen-checkpoint':speak(chapter().quiz.q);break;
case 'word':showWord(b.dataset.word);break;
case 'vocab-speak':pronounceWord(b.dataset.word);break;
case 'save-word':C.toggle(p.saved,b.dataset.word);save();render();break;
case 'modal-save-word':C.toggle(p.saved,b.dataset.word);save();b.innerHTML=icon('bookmark')+(p.saved.includes(b.dataset.word)?'已收藏':'加入词语背包');toast(p.saved.includes(b.dataset.word)?'已经放进词语背包。':'已移出收藏。');break;
case 'learn-word':C.toggle(p.words,b.dataset.word);save();render();break;
case 'word-context':wordContext(b.dataset.word);break;
case 'word-filter':wordFilter=b.dataset.filter;render();break;
case 'word-mode':wordMode=b.dataset.mode;stopSpeech();render();break;
case 'new-match':newMatch();render();break;
case 'match-left':matchLeft=i;matchSelection=null;pronounceWord(matchWords[i][0]);render();break;
case 'match-right':if(matchLeft===null){toast('先点左边的英文词语。');break;}if(i===matchLeft){C.add(matchDone,i);C.add(p.match,matchWords[i][0]);matchLeft=null;matchSelection=null;save();render();toast(matchDone.length===5?'这一组全部配对成功！':'配对成功！');}else{matchSelection=i;render();toast('再试试。可以重新听英文，也可以回词卡看看。');}break;
case 'challenge-tab':stopSpeech();clearTimeout(timer);quizSession++;challenge=b.dataset.tab;render();break;
case 'quiz-answer':answerQuiz(i);break;
case 'quiz-hint':qHint=!qHint;render();break;
case 'next-question':nextQuestion();break;
case 'listen-question':speak(questions[qIndex].q);break;
case 'jump-evidence':clearTimeout(timer);quizSession++;gotoChapter(Number(b.dataset.chapter),Number(b.dataset.sentence));translation=true;render();break;
case 'restart-quiz':qIndex=0;qFeedback=null;qHint=false;quizDone=false;quizSession++;render();break;
case 'order-add':if(!orderAnswer.includes(i))orderAnswer.push(i);orderFeedback='';render();break;
case 'order-remove':orderAnswer.splice(i,1);orderFeedback='';render();break;
case 'order-reset':orderAnswer=[];orderFeedback='';orderPool=C.shuffle(orderPool);render();break;
case 'order-check':orderFeedback=C.orderCorrect(orderAnswer,6)?'correct':'wrong';if(orderFeedback==='correct'){p.ordered=true;save();}render();break;
case 'builder-add':if(!builderAnswer.includes(i))builderAnswer.push(i);builderFeedback='';render();break;
case 'builder-remove':builderAnswer.splice(i,1);builderFeedback='';render();break;
case 'builder-listen':speak(L.builders[builder].parts.join(' '));break;
case 'builder-check':builderFeedback=C.orderCorrect(builderAnswer,L.builders[builder].parts.length)?'correct':'wrong';if(builderFeedback==='correct'){C.add(p.builders,builder);save();}render();if(builderFeedback==='correct')speak(L.builders[builder].parts.join(' '));break;
case 'builder-next':resetBuilder((builder+1)%L.builders.length);render();break;
case 'retell-hints':retellHints=!retellHints;render();break;
case 'retell-line':speak(L.retelling[i].en);break;
case 'retell-listen':speakSequence(L.retelling.map(r=>({text:r.en})));break;
case 'record-start':await startRecord();break;
case 'record-stop':stopRecord();break;
case 'save-draft':save();toast('复述文字和自查项目已保存。');break;
case 'extension-tab':stopSpeech();extension=b.dataset.tab;render();break;
case 'museum-listen':speak(L.museumTexts[Number(b.dataset.museum)].sentences[i][0]);break;
case 'museum-match':museumMatches[i]=b.dataset.value;render();break;
case 'role-select':stopSpeech();role=b.dataset.role;render();break;
case 'role-next':stopSpeech();roleIndex=(roleIndex+1)%L.roles.length;render();break;
case 'role-listen':speak(L.roles[roleIndex][b.dataset.line]);break;
case 'ad-source-listen':speak(L.advert[i][0]);break;
case 'ad-listen':{const ad=advertText();speak(ad.title+' '+ad.text);break;}
case 'ad-copy':{const ad=advertText();try{await navigator.clipboard.writeText(ad.title+'\n\n'+ad.text);toast('广告文字已复制。');}catch{toast('此浏览器不支持直接复制，可以选择“保存文字文件”。');}break;}
case 'ad-download':{const ad=advertText();download('我的博物馆广告.txt',ad.title+'\n\n'+ad.text,'text/plain;charset=utf-8');break;}
case 'capsule':if(!p.capsule.includes(b.dataset.value)&&p.capsule.length>=4){toast('胶囊里先放四样；点已选物品可以换掉它。');break;}C.toggle(p.capsule,b.dataset.value);save();render();break;
case 'capsule-listen':speak('I want to put '+p.capsule.join(', ')+' in my time capsule.');break;
case 'chapter-text':stopSpeech();showChapterText();break;
case 'modal-chapter-speak':speakSequence(chapter().sentences.map(s=>({text:s.en})));break;
case 'modal-chinese-speak':speak(chapter().sentences.map(s=>s.zh).join(''),'zh-CN');break;
case 'source':stopSpeech();showSource();break;
case 'source-page':stopSpeech();showSource(i);break;
case 'source-text':stopSpeech();showSource();break;
case 'settings':stopSpeech();showSettings();break;
case 'refresh-voices':showSettings();break;
case 'voice-test':speak('Hello, little detective. Let us read the story together.');break;
case 'report':stopSpeech();showReport();break;
case 'close-modal':closeModal();break;
case 'print':window.print();break;
case 'export-progress':download('金猫故事_学习进度备份.json',JSON.stringify({lessonId:L.id,...reportObject()},null,2));break;
case 'import-progress':document.getElementById('progress-file').click();break;
case 'reset-dialog':openModal('重新开始这次探险',`<p class="muted mb">会清除当前浏览器里的本课进度、收藏和复述草稿。你可以先导出备份。</p><div class="flex">${btn('先导出备份','export-progress','download')}${btn('确认清除并开始','reset-all','repeat','danger')}${btn('保留进度','close-modal','back')}</div>`);break;
case 'reset-all':p=C.initial();save();closeModal();checkpoint=false;view='read';qIndex=0;qFeedback=null;quizDone=false;orderAnswer=[];orderFeedback='';resetBuilder(0);newMatch();render();toast('新的探险开始了。');break;
}});
document.addEventListener('input',event=>{lastInteraction=Date.now();const t=event.target;if(t.id==='vocab-search'){search=t.value;const list=L.vocabulary.filter(w=>(wordFilter==='all'||wordFilter==='saved'&&p.saved.includes(w[0])||wordFilter==='review'&&!p.words.includes(w[0])||wordFilter==='learned'&&p.words.includes(w[0]))&&(!search||(w[0]+' '+w[1]).toLowerCase().includes(search.toLowerCase())));document.getElementById('word-list').innerHTML=renderWordCards(list);}if(t.id==='retell-draft'){p.draft=t.value.slice(0,12000);save();}if(t.dataset.ad){p.advert[t.dataset.ad]=t.value.slice(0,200);save();updateAdPreview();}});
document.addEventListener('change',async event=>{const t=event.target;if(t.id==='rate'||t.id==='setting-rate'){stopSpeech();p.settings.rate=Number(t.value);save();}if(t.id==='voice-select'){p.settings.voice=t.value;save();}if(t.id==='zh-voice-select'){p.settings.chineseVoice=t.value;save();}if(t.id==='repeat-setting'){p.settings.repeat=t.checked;save();}if(t.id==='auto-next'){p.settings.autoNext=t.checked;clearTimeout(timer);save();if(qFeedback?.correct)render();}if(t.dataset.check!==undefined){C.toggle(p.retellChecks,Number(t.dataset.check));save();}if(t.id==='progress-file'&&t.files[0]){try{if(t.files[0].size>1000000)throw Error('size');const data=JSON.parse(await t.files[0].text());if(data.lessonId!==L.id||!data.progress||typeof data.progress!=='object')throw Error('lesson');const sanitized=C.clean(data.progress,L);openModal('恢复这份学习进度',`<p class="muted mb">备份包含 ${sanitized.read.length} 个自评会读单元。恢复后会替换当前设备的本课记录。</p><div class="flex">${btn('恢复这份备份','restore-confirm','check','primary')}${btn('保留当前记录','close-modal','back')}</div>`);const button=document.querySelector('[data-action="restore-confirm"]');button.addEventListener('click',()=>{stopSpeech();clearTimeout(timer);quizSession++;p=sanitized;save();closeModal();checkpoint=false;view='read';render();toast('学习进度已恢复。');},{once:true});}catch{toast('这份文件不是本课有效的进度备份，请选择本页导出的 JSON 文件。');}}});
document.getElementById('modal').addEventListener('cancel',()=>stopSpeech());
document.getElementById('modal').addEventListener('click',event=>{if(event.target===event.currentTarget){const r=event.currentTarget.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
document.addEventListener('keydown',event=>{lastInteraction=Date.now();if(event.target.matches('input,textarea,select,button')||document.getElementById('modal').open)return;if(view==='read'&&!checkpoint&&event.key===' '){event.preventDefault();speaking?stopSpeech():listenCurrent();}});
document.addEventListener('visibilitychange',()=>{lastTick=Date.now();if(document.hidden){stopSpeech();if(recorder?.state==='recording')stopRecord();save();}});
window.addEventListener('pagehide',()=>{stopSpeech();if(recordStream)recordStream.getTracks().forEach(t=>t.stop());save();});
setInterval(()=>{const now=Date.now(),delta=Math.min(15,(now-lastTick)/1000);if(!document.hidden&&now-lastInteraction<180000){p.activeSeconds+=delta;save();}lastTick=now;},10000);
if('speechSynthesis' in window)window.speechSynthesis.addEventListener('voiceschanged',()=>{const en=document.getElementById('voice-select'),zh=document.getElementById('zh-voice-select');if(en)en.innerHTML=voiceOptions('en',p.settings.voice);if(zh)zh.innerHTML=voiceOptions('zh',p.settings.chineseVoice);});
if(window.location.protocol==='file:')document.body.classList.add('offline');
render();
})();
